/* Local transaction/review prototype. Production must enforce these rules on the API. */
state.transactions=Array.isArray(stored.transactions)?stored.transactions:[];
state.reviews=Array.isArray(stored.reviews)?stored.reviews:[];
function validCustomerReviews(providerId){return state.reviews.filter(review=>{
  const transaction=state.transactions.find(item=>item.id===review.transactionId);
  return review.providerId===providerId&&transaction?.status==='completed'&&transaction.providerId===providerId&&transaction.customerId===review.customerId&&review.customerId!==providerId&&profiles.some(p=>p.id===review.customerId)&&Number.isInteger(review.stars)&&review.stars>=1&&review.stars<=5;
});}
function memberRating(id){const reviews=validCustomerReviews(id);return {count:reviews.length,average:reviews.length?reviews.reduce((sum,r)=>sum+r.stars,0)/reviews.length:0};}
function ratingHtml(id){const rating=memberRating(id);return rating.count?`<div class="member-rating"><span data-no-translate>★ ${rating.average.toFixed(1)} / 5 · ${rating.count}</span> <span>customer reviews</span></div>`:'<p class="muted">No customer reviews yet</p>';}
function listingPrice(listing,basis='kg'){const amount=Number(listing.priceAmount);return listing.intent==='offer'&&listing.priceBasis===basis&&listing.priceAmount!==undefined&&Number.isFinite(amount)&&amount>0?amount:null;}
function memberPrice(id,basis='kg'){const prices=all().filter(l=>l.profileId===id&&l.category==='produce').map(l=>listingPrice(l,basis)).filter(p=>p!==null);return prices.length?Math.min(...prices):null;}
function compareOptionalPrice(a,b,descending=false){if(a===null&&b===null)return 0;if(a===null)return 1;if(b===null)return -1;return descending?b-a:a-b;}
function memberSort(members,sort='new',basis='kg'){const indexed=new Map(profiles.map((p,i)=>[p.id,i]));const newest=(a,b)=>Date.parse(b.createdAt||b.wholesaleAcceptedAt||'1970-01-01')-Date.parse(a.createdAt||a.wholesaleAcceptedAt||'1970-01-01')||(indexed.get(b.id)-indexed.get(a.id));return [...members].sort((a,b)=>{
  if(sort==='price-asc'||sort==='price-desc')return compareOptionalPrice(memberPrice(a.id,basis),memberPrice(b.id,basis),sort==='price-desc')||newest(a,b);
  if(sort==='rating'){const first=memberRating(a.id),second=memberRating(b.id);return second.average-first.average||second.count-first.count||newest(a,b);}
  return newest(a,b);
});}
window.sortMarketplace=(rows,sort)=>[...rows].sort((a,b)=>{
  if(sort==='price-asc'||sort==='price-desc')return compareOptionalPrice(listingPrice(a),listingPrice(b),sort==='price-desc');
  if(sort==='rating')return memberRating(b.profileId).average-memberRating(a.profileId).average;
  return Date.parse(b.createdAt||'1970-01-01')-Date.parse(a.createdAt||'1970-01-01');
});
function saveCommunityState(changes){const next={...state,...changes};try{localStorage.setItem('fd-preview-v1',JSON.stringify(next));state=next;return true;}catch{toast('Browser storage is full or unavailable. This change could not be saved.');return false;}}
function communityResult(ok,message){return {ok,message:ok?message:'Browser storage is full or unavailable. This change could not be saved.'};}
function requestCompletion(providerId,input){const customer=currentProfile(),provider=profiles.find(p=>p.id===providerId);if(!customer||!provider||providerId===customer.id)return {ok:false,message:'Sign in as the customer of this member.'};const reference=String(input.reference||'').trim(),description=String(input.description||'').trim();if(!reference||reference.length>120||!description||description.length>500)return {ok:false,message:'Enter the transaction reference and service details.'};if(state.transactions.some(t=>t.providerId===providerId&&t.customerId===customer.id&&t.reference.toLowerCase()===reference.toLowerCase()))return {ok:false,message:'This transaction is already recorded.'};const transaction={id:crypto.randomUUID(),providerId,customerId:customer.id,reference,description,status:'pending',requestedAt:new Date().toISOString()};return communityResult(saveCommunityState({transactions:[transaction,...state.transactions]}),'Completion confirmation requested.');}
function confirmCompletion(transactionId){const provider=currentProfile(),transaction=state.transactions.find(t=>t.id===transactionId);if(!provider||!transaction||transaction.providerId!==provider.id||transaction.customerId===provider.id||transaction.status!=='pending'||!profiles.some(p=>p.id===transaction.customerId))return {ok:false,message:'Only the provider can confirm this transaction.'};return communityResult(saveCommunityState({transactions:state.transactions.map(t=>t.id!==transactionId?t:{...t,status:'completed',confirmedAt:new Date().toISOString()})}),'Transaction confirmed as completed.');}
function submitCustomerReview(transactionId,input){const customer=currentProfile(),transaction=state.transactions.find(t=>t.id===transactionId);if(!customer||!transaction||transaction.customerId!==customer.id||transaction.providerId===customer.id||transaction.status!=='completed'||!profiles.some(p=>p.id===transaction.providerId))return {ok:false,message:'Only the customer of a confirmed completed transaction can review.'};if(state.reviews.some(r=>r.transactionId===transactionId))return {ok:false,message:'You have already reviewed this transaction.'};const stars=Number(input.stars),comment=String(input.comment||'').trim();if(!Number.isInteger(stars)||stars<1||stars>5||comment.length<10||comment.length>1500)return {ok:false,message:'Choose 1 to 5 stars and write at least 10 characters.'};const review={id:crypto.randomUUID(),transactionId,providerId:transaction.providerId,customerId:customer.id,stars,comment,createdAt:new Date().toISOString()};return communityResult(saveCommunityState({reviews:[review,...state.reviews]}),'Customer review saved.');}
function customerReviewsHtml(provider){const current=currentProfile(),reviews=validCustomerReviews(provider.id),transactions=state.transactions.filter(t=>t.providerId===provider.id),mine=current?transactions.filter(t=>t.customerId===current.id):[];
  return `<section class="customer-reviews"><h3>Customer reviews</h3>${ratingHtml(provider.id)}<p class="muted">Reviews require a completed purchase or service confirmed by the provider. One review per transaction. This local demo does not verify real-world delivery.</p>${reviews.map(review=>`<article class="review-row"><strong data-no-translate>${safe(profiles.find(p=>p.id===review.customerId)?.name||'—')}</strong><span data-no-translate> ★ ${review.stars} / 5</span><p data-no-translate>${safe(review.comment)}</p><small>Completed transaction · locally confirmed</small></article>`).join('')}${!current?'<p>Sign in to record a completed purchase or service.</p>':current.id===provider.id?`<h3>Confirm completed transactions</h3>${transactions.filter(t=>t.status==='pending').map(t=>`<article class="review-row"><strong data-no-translate>${safe(profiles.find(p=>p.id===t.customerId)?.name||'—')}</strong><p data-no-translate>${safe(t.reference)} · ${safe(t.description)}</p><button class="primary" data-confirm-service="${safe(t.id)}">Confirm service received / delivered</button></article>`).join('')||'<p>No pending confirmations</p>'}`:`<h3>Your purchases and services</h3>${mine.map(t=>`<article class="review-row"><strong data-no-translate>${safe(t.reference)}</strong><p>${t.status==='completed'?'Completion confirmed':'Awaiting provider confirmation'}</p>${t.status==='completed'&&!state.reviews.some(r=>r.transactionId===t.id)?`<form data-review-form="${safe(t.id)}"><label>Star rating<select name="stars" required><option value="">Choose rating</option>${[5,4,3,2,1].map(n=>`<option value="${n}">${'★'.repeat(n)}</option>`).join('')}</select></label><label>Your customer review<textarea name="comment" required minlength="10" maxlength="1500" rows="3"></textarea></label><button class="primary">Submit customer review</button></form>`:state.reviews.some(r=>r.transactionId===t.id)?'<p>Review already submitted</p>':''}</article>`).join('')}<form id="service-completion-form"><h3>Already received a purchase or service?</h3><p class="muted">Record it here and ask this member to confirm completion before you can review.</p><label>Transaction reference<input name="reference" required maxlength="120"></label><label>Purchase or service received<textarea name="description" required maxlength="500" rows="2"></textarea></label><button class="primary">Request completion confirmation</button></form>`}</section>`;
}
function bindCustomerReviews(provider){const form=$('#service-completion-form');if(form)form.onsubmit=event=>{event.preventDefault();if(!event.target.reportValidity())return;const result=requestCompletion(provider.id,Object.fromEntries(new FormData(event.target)));if(result.ok){showMember(provider.id);render();}toast(result.message);};document.querySelectorAll('[data-review-form]').forEach(form=>form.onsubmit=event=>{event.preventDefault();if(!event.target.reportValidity())return;const result=submitCustomerReview(form.dataset.reviewForm,Object.fromEntries(new FormData(form)));if(result.ok){showMember(provider.id);render();}toast(result.message);});document.querySelectorAll('[data-confirm-service]').forEach(button=>button.onclick=()=>{const result=confirmCompletion(button.dataset.confirmService);if(result.ok){showMember(provider.id);render();}toast(result.message);});}
